    var peak = arr[0];
    for (var i = 1; i < arr.length; i++) {
        // Bandingkan kekuatan getaran (magnitudo) tanpa menghilangkan tanda +/-
        if (Math.abs(arr[i]) > Math.abs(peak)) {
