// ================================
// ANALISIS FFT RODA (FULL VERSION)
// ================================

// --- 1. PARAMETER ---
var inputData = msg.payload.slice(); // copy array
var Fs = 200; // Sampling frequency

// --- 2. ZERO PADDING KE PANGKAT 2 ---
function nextPowerOf2(n){
    return Math.pow(2, Math.ceil(Math.log2(n)));
}

var originalLength = inputData.length;
var N = nextPowerOf2(originalLength);

while(inputData.length < N){
    inputData.push(0);
}

// --- 3. MEAN REMOVAL ---
let mean = inputData.reduce((a,b)=>a+b,0)/N;
inputData = inputData.map(v => v - mean);

// --- 4. HAMMING WINDOW ---
inputData = inputData.map((v,n)=>{
    let w = 0.54 - 0.46 * Math.cos((2*Math.PI*n)/(N-1));
    return v*w;
});

// --- 5. FFT COOLEY-TUKEY RECURSIVE ---
function fft(signal){
    var N = signal.length;
    if(N <= 1) return [{re: signal[0], im: 0}];

    var even = [];
    var odd = [];

    for(var i=0;i<N;i++){
        (i%2===0 ? even : odd).push(signal[i]);
    }

    even = fft(even);
    odd = fft(odd);

    var T = new Array(N);

    for(var k=0;k<N/2;k++){
        var angle = -2*Math.PI*k/N;
        var cos = Math.cos(angle);
        var sin = Math.sin(angle);

        var tre = cos*odd[k].re - sin*odd[k].im;
        var tim = sin*odd[k].re + cos*odd[k].im;

        T[k] = {
            re: even[k].re + tre,
            im: even[k].im + tim
        };

        T[k+N/2] = {
            re: even[k].re - tre,
            im: even[k].im - tim
        };
    }
    return T;
}

var fftResult = fft(inputData);

// --- 6. MAGNITUDE & PEAK DETECTION ---
var spectrum = [];
var maxVal = 0;
var peakFreq = 0;
var noiseThreshold = 0.03;
var maxFreqTarget = 100;

for(let k=1; k<N/2; k++){
    let magnitude = (Math.sqrt(
        fftResult[k].re*fftResult[k].re +
        fftResult[k].im*fftResult[k].im
    ) / N) * 2;

    let freq = k * Fs / N;

    if(freq <= maxFreqTarget){
        spectrum.push({freq: freq, val: magnitude});

        if(magnitude > maxVal && magnitude > noiseThreshold){
            maxVal = magnitude;
            peakFreq = parseFloat(freq.toFixed(1));
        }
    }
}

if(maxVal < noiseThreshold){
    peakFreq = 0;
    maxVal = 0;
}

